package com.leetcode.backend.model;

import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notification_deliveries",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","type","entity_type","entity_id"}),indexes={@Index(name="idx_notification_status",columnList="status,created_at"),@Index(name="idx_notification_entity",columnList="entity_type,entity_id")})
public class NotificationDelivery {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,length=50) private String type; @Column(name="entity_type",nullable=false,length=40) private String entityType; @Column(name="entity_id",nullable=false) private Long entityId; @Column(nullable=false,length=150) private String recipient; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private AssessmentEnums.DeliveryStatus status=AssessmentEnums.DeliveryStatus.PENDING; @Column(name="attempt_count",nullable=false) private int attemptCount; @Column(name="sent_at") private LocalDateTime sentAt; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @Column(name="last_error",length=500) private String lastError;
 @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getEntityType(){return entityType;} public void setEntityType(String v){entityType=v;} public Long getEntityId(){return entityId;} public void setEntityId(Long v){entityId=v;} public String getRecipient(){return recipient;} public void setRecipient(String v){recipient=v;} public AssessmentEnums.DeliveryStatus getStatus(){return status;} public void setStatus(AssessmentEnums.DeliveryStatus v){status=v;} public int getAttemptCount(){return attemptCount;} public void setAttemptCount(int v){attemptCount=v;} public LocalDateTime getSentAt(){return sentAt;} public void setSentAt(LocalDateTime v){sentAt=v;} public void setLastError(String v){lastError=v==null?null:v.substring(0,Math.min(500,v.length()));}
}
